"""Build reviewed account/role plans and drafts from the saved research. No sends."""
import csv, json, pathlib
DIR=pathlib.Path('partnership-system/markets/ca/on/windsor-essex/runs/2026-09-15/priority-enrichment')
accounts=json.loads((DIR/'accounts-config.json').read_text())
history={a['key']:a for a in json.loads((DIR/'history-summary.json').read_text())}
plans=[];routes=[]
def account(name,local,source,channel,route,address,city,notes):
 a=next(x for x in accounts if x['name']==name)
 p={**a,'local_presence_evidence':local,'local_source':source,'recommended_channel':channel,'primary_route':route,'verified_mailing_address':address,'city':city,'review_notes':notes,'history':history[a['key']],'role_gaps':['Facilities/workplace decision-maker','Local operations or project sponsor','Indirect procurement/service contracting owner'],'outreach_state':'research_or_draft_only','reviewed_at':'2026-09-15'}
 plans.append(p);return p
def contact(name,person,title,email,source,priority='secondary',status='current_official_publication',phone=''):
 a=next(x for x in accounts if x['name']==name)
 routes.append(dict(account_key=a['key'],account_name=name,name=person,title=title,email=email,source_url=source,priority=priority,evidence_status=status,phone=phone,mailbox_verification='not_performed',permission_status='review_required',sequence_paused=True))

